import{_ as s,o as t,c as o,a2 as i}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Vercel","description":"Vercel reference documentation","frontmatter":{"title":"Vercel","description":"Vercel reference documentation"},"headers":[],"relativePath":"knowledge/vercel.md","filePath":"knowledge/vercel.md","lastUpdated":1784485118000}'),a={name:"knowledge/vercel.md"};function n(r,e,l,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-label="Permalink to &quot;Vercel&quot;">​</a></h1><h1 id="vercel-knowledge-document" tabindex="-1">Vercel Knowledge Document <a class="header-anchor" href="#vercel-knowledge-document" aria-label="Permalink to &quot;Vercel Knowledge Document&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Vercel is a frontend cloud platform optimized for Next.js and modern web frameworks. It provides zero-configuration deployments, serverless/edge functions, ISR/SSR/SSG support, image optimization, analytics, and global CDN. Vercel is the default deployment target for Ahmed&#39;s workspace projects, offering seamless integration with Next.js App Router and Git-based workflows.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="deployment-model" tabindex="-1">Deployment Model <a class="header-anchor" href="#deployment-model" aria-label="Permalink to &quot;Deployment Model&quot;">​</a></h3><p>Vercel deploys from Git repositories (GitHub, GitLab, Bitbucket). Pushing to the main branch triggers a production deployment. Every push creates a unique deployment URL for preview. Vercel builds, optimizes, and distributes your application to its global edge network automatically.</p><h3 id="rendering-strategies" tabindex="-1">Rendering Strategies <a class="header-anchor" href="#rendering-strategies" aria-label="Permalink to &quot;Rendering Strategies&quot;">​</a></h3><ul><li><strong>SSG (Static Site Generation)</strong> — Pages are pre-rendered at build time. Fastest possible performance. Use for: marketing pages, blog posts, documentation.</li><li><strong>SSR (Server-Side Rendering)</strong> — Pages are rendered on every request at the edge. Use for: personalized content, user-specific data.</li><li><strong>ISR (Incremental Static Regeneration)</strong> — Pages are statically generated but revalidated periodically or on-demand. Use for: product pages, content that changes infrequently.</li><li><strong>Edge Rendering</strong> — Pages rendered on Vercel&#39;s edge network (V8 isolates, ~50ms cold start). Use for: latency-sensitive dynamic content.</li></ul><h3 id="edge-functions-vs-serverless-functions" tabindex="-1">Edge Functions vs Serverless Functions <a class="header-anchor" href="#edge-functions-vs-serverless-functions" aria-label="Permalink to &quot;Edge Functions vs Serverless Functions&quot;">​</a></h3><ul><li><strong>Edge Functions:</strong> Run on V8 isolates at the edge. Cold start &lt;50ms. Limited APIs (no Node.js <code>fs</code>, limited crypto). Use for: middleware, A/B testing, geolocation, auth checks.</li><li><strong>Serverless Functions:</strong> Run on Node.js in AWS Lambda. Cold start 100-500ms. Full Node.js API. Use for: database queries, heavy computation, file processing.</li></ul><h3 id="middleware" tabindex="-1">Middleware <a class="header-anchor" href="#middleware" aria-label="Permalink to &quot;Middleware&quot;">​</a></h3><p>Middleware runs before a request is completed. It can modify headers, redirect, rewrite URLs, and implement authentication. Middleware runs at the edge globally. Place it at <code>src/middleware.ts</code> or <code>middleware.ts</code>.</p><h3 id="image-optimization" tabindex="-1">Image Optimization <a class="header-anchor" href="#image-optimization" aria-label="Permalink to &quot;Image Optimization&quot;">​</a></h3><p><code>next/image</code> with Vercel automatically optimizes images: format conversion (WebP/AVIF), responsive resizing, lazy loading, and CDN caching. Configure remote patterns in <code>next.config.js</code>.</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exports</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  images: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    remotePatterns: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      { protocol: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, hostname: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;images.unsplash.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="analytics-and-speed-insights" tabindex="-1">Analytics and Speed Insights <a class="header-anchor" href="#analytics-and-speed-insights" aria-label="Permalink to &quot;Analytics and Speed Insights&quot;">​</a></h3><p>Vercel Analytics tracks Web Vitals (LCP, FID, CLS, TTFB) and custom metrics. Speed Insights provides real-user performance data. Both are privacy-focused and don&#39;t use cookies.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Use ISR over SSR for most dynamic pages</strong> — ISR gives you static performance with dynamic content. Set <code>revalidate: 60</code> for pages that update every minute. Use <code>revalidatePath()</code> for on-demand revalidation.</p></li><li><p><strong>Place authentication in Middleware</strong> — Middleware runs before any page or API route. Check auth tokens, redirect unauthorized users, and set request headers in <code>src/middleware.ts</code>.</p></li><li><p><strong>Use Edge Runtime for API routes when possible</strong> — Edge API routes have &lt;50ms cold starts and run globally. Use <code>export const runtime = &#39;edge&#39;</code> for routes that don&#39;t need Node.js APIs.</p></li><li><p><strong>Configure <code>next.config.js</code> for Vercel optimization</strong> — Enable <code>output: &#39;standalone&#39;</code> for smaller builds. Configure image domains, redirects, and rewrites in <code>next.config.js</code>.</p></li><li><p><strong>Use Environment Variables correctly</strong> — Prefix public variables with <code>NEXT_PUBLIC_</code>. Server-only variables are automatically excluded from the client bundle. Configure in Vercel Dashboard or <code>.env</code> files.</p></li><li><p><strong>Use Vercel CLI for local development</strong> — <code>vercel dev</code> replicates the Vercel environment locally, including edge functions, serverless functions, and environment variables.</p></li><li><p><strong>Leverage preview deployments for PRs</strong> — Every pull request gets a unique preview URL. Use this for visual regression testing, stakeholder review, and integration testing.</p></li><li><p><strong>Set up domain configuration early</strong> — Add custom domains in the Vercel Dashboard. Vercel handles SSL certificates automatically. Use <code>vercel domains add</code> via CLI.</p></li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><p><strong>Using <code>getServerSideProps</code> for everything</strong> — <code>getServerSideProps</code> runs on every request and defeats caching. Use ISR (<code>getStaticProps</code> with <code>revalidate</code>) or Edge Runtime when possible.</p></li><li><p><strong>Ignoring bundle size</strong> — Vercel deploys the entire bundle to the edge. Use dynamic imports (<code>next/dynamic</code>), tree shaking, and the <code>@next/bundle-analyzer</code> to keep bundles small.</p></li><li><p><strong>Hardcoding environment-specific URLs</strong> — Use environment variables for API endpoints, database URLs, and service URLs. Never hardcode production URLs in code.</p></li><li><p><strong>Not using <code>next/image</code> for images</strong> — Raw <code>&lt;img&gt;</code> tags bypass Vercel&#39;s optimization pipeline. Always use <code>next/image</code> for performance benefits.</p></li><li><p><strong>Deploying without running <code>next build</code> locally</strong> — Test builds locally before pushing. <code>next build</code> catches TypeScript errors, missing dependencies, and configuration issues.</p></li><li><p><strong>Ignoring Edge Runtime limitations</strong> — Edge Runtime doesn&#39;t support all Node.js APIs. Test edge-compatible code locally with <code>vercel dev --edge</code>.</p></li><li><p><strong>Using <code>fetch</code> without caching configuration</strong> — Next.js 15+ caches fetch by default. Use <code>{ cache: &#39;no-store&#39; }</code> for real-time data or <code>{ next: { revalidate: 60 } }</code> for ISR.</p></li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><p><strong>Forgetting <code>NEXT_PUBLIC_</code> prefix for client-side env vars</strong> — Variables without this prefix are not exposed to the client bundle. This causes undefined values in browser code.</p></li><li><p><strong>Not handling deployment failures</strong> — Vercel sends deployment notifications. Set up Slack/Discord notifications and check build logs for failed deployments.</p></li><li><p><strong>Using <code>res.json()</code> in Edge Runtime</strong> — Edge functions use Web APIs: <code>Response.json()</code>, not <code>res.json()</code>. The <code>res</code> object is only available in Node.js runtime.</p></li><li><p><strong>Missing <code>export const dynamic = &#39;force-dynamic&#39;</code></strong> — Next.js 15+ statically renders by default. Add this export to pages that need dynamic rendering.</p></li><li><p><strong>Not configuring <code>rewrites</code> for API proxying</strong> — Use <code>rewrites</code> in <code>next.config.js</code> to proxy API calls to external services. This avoids CORS issues and keeps API keys server-side.</p></li><li><p><strong>Ignoring Vercel&#39;s function timeout limits</strong> — Free tier: 10s (Serverless), 30s (Edge). Pro tier: 300s (Serverless), 30s (Edge). Design functions to complete within limits.</p></li><li><p><strong>Not using <code>vercel pull</code> to sync env vars</strong> — <code>vercel pull</code> downloads environment variables from Vercel to your local <code>.env.local</code>. This keeps local and production environments in sync.</p></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><ul><li><strong>Use Vercel when:</strong> Your project is Next.js-based, you want zero-config deployment, or you need global edge performance with minimal infrastructure management.</li><li><strong>Use SSR when:</strong> Content changes per-request and requires real-time data (user dashboards, admin panels).</li><li><strong>Use ISR when:</strong> Content updates periodically but should serve from cache (product pages, blog posts, documentation).</li><li><strong>Use SSG when:</strong> Content rarely changes (landing pages, about pages, legal pages).</li><li><strong>Use Edge Functions when:</strong> You need low-latency logic at the edge (auth, A/B testing, geolocation).</li><li><strong>Use Serverless Functions when:</strong> You need Node.js APIs, database access, or heavy computation.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Vercel Docs: <a href="https://vercel.com/docs" target="_blank" rel="noreferrer">https://vercel.com/docs</a></li><li>Next.js Docs: <a href="https://nextjs.org/docs" target="_blank" rel="noreferrer">https://nextjs.org/docs</a></li><li>Vercel Blog: <a href="https://vercel.com/blog" target="_blank" rel="noreferrer">https://vercel.com/blog</a></li><li>Vercel CLI: <a href="https://vercel.com/docs/cli" target="_blank" rel="noreferrer">https://vercel.com/docs/cli</a></li><li>Vercel Templates: <a href="https://vercel.com/templates" target="_blank" rel="noreferrer">https://vercel.com/templates</a></li><li>Next.js Learn: <a href="https://nextjs.org/learn" target="_blank" rel="noreferrer">https://nextjs.org/learn</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><code>vercel</code> deploys to preview; <code>vercel --prod</code> deploys to production.</li><li><code>vercel env add</code> adds environment variables; <code>vercel env pull</code> downloads them locally.</li><li><code>vercel logs &lt;deployment-url&gt;</code> streams real-time logs for a deployment.</li><li><code>vercel inspect &lt;deployment-url&gt;</code> shows deployment details and function logs.</li><li>Vercel automatically detects the framework (Next.js, Remix, Astro, etc.) from <code>package.json</code>.</li><li>Use <code>vercel.json</code> for advanced configuration: redirects, rewrites, headers, functions config.</li><li>Vercel&#39;s free tier: 100GB bandwidth, 1000 build minutes/month, unlimited deployments.</li><li>For monorepos, configure <code>vercel.json</code> with <code>buildCommand</code> and <code>outputDirectory</code> per package.</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>`,32)])])}const u=s(a,[["render",n]]);export{h as __pageData,u as default};
